contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 ms) internal {
        vm.assume(ms > 0);
        try c.SetMinSum(ms) {} catch { return; }
        try c.SetLogFile(address(this)) {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint ethBefore = address(c).balance;
        bool reverted;
        try c.Collect(ms) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && c.balances(address(this)) == balBefore && address(c).balance == ethBefore && c.MinSum() == ms);
    }

    function testFuzz_run(uint256 ms) public {
        _run(ms);
    }

    receive() external payable {}

    fallback() external payable {}
